import { useSession } from "../lib/auth-client"

export default function ProfileSection() {
  const { data: session } = useSession()
  const user = session!.user
  const initial = user.name.charAt(0).toUpperCase()

  return (
    {/* impeccable-carbonize-start dd6d2a95 */}
    <style data-impeccable-css="dd6d2a95">{`
    @scope ([data-impeccable-variant="1"]) {
    :scope > .profile-card {
    animation: cr-1 350ms cubic-bezier(0.22, 1, 0.36, 1) both;
    }
    :scope > .profile-card .avatar {
    animation: ap-1 350ms cubic-bezier(0.25, 1, 0.5, 1) 80ms both;
    }
    :scope > .profile-card .name-group {
    animation: ts-1 250ms cubic-bezier(0.25, 1, 0.5, 1) 160ms both;
    }
    :scope > .profile-card .id-group {
    animation: fu-1 200ms cubic-bezier(0.25, 1, 0.5, 1) 300ms both;
    }
    @keyframes cr-1 { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes ap-1 { from { opacity: 0; transform: scale(0); } to { opacity: 1; transform: scale(1); } }
    @keyframes ts-1 { from { opacity: 0; transform: translateX(-10px); } to { opacity: 1; transform: translateX(0); } }
    @keyframes fu-1 { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
    }
    @scope ([data-impeccable-variant="2"]) {
    :scope > .profile-card {
    animation: cz-2 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
    }
    :scope > .profile-card .avatar {
    animation: ag-2 450ms cubic-bezier(0.25, 1, 0.5, 1) both;
    }
    :scope > .profile-card .name-group {
    animation: fb-2 250ms cubic-bezier(0.25, 1, 0.5, 1) 180ms both;
    }
    :scope > .profile-card .id-group {
    animation: fu-2 200ms cubic-bezier(0.25, 1, 0.5, 1) 280ms both;
    }
    @keyframes cz-2 { from { opacity: 0; transform: scale(0.96); } to { opacity: 1; transform: scale(1); } }
    @keyframes ag-2 { 0% { opacity: 0; transform: scale(0); box-shadow: 0 0 0 0 var(--primary); } 40% { opacity: 1; transform: scale(1.08); box-shadow: 0 0 0 8px color-mix(in oklch, var(--primary) 15%, transparent); } 100% { opacity: 1; transform: scale(1); box-shadow: 0 0 0 0 var(--primary); } }
    @keyframes fb-2 { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes fu-2 { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
    }
    `}</style>
    {/* impeccable-carbonize-end dd6d2a95 */}
    <div data-impeccable-variant="2" style={{ display: 'contents' }}>
    <div className="profile-card rounded-xl bg-card p-5">
      <div className="flex items-center gap-4">
        <div className="avatar flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-primary/10 text-primary text-base font-semibold">
          {initial}
        </div>
        <div className="name-group min-w-0">
          <h3 className="text-base font-semibold text-foreground">{user.name}</h3>
          <p className="text-sm text-muted-foreground truncate">{user.email}</p>
        </div>
      </div>
      <div className="id-group mt-4 pt-4 border-t border-border/50">
        <div className="flex items-center justify-between">
          <span className="text-xs text-muted-foreground">User ID</span>
          <span className="text-xs font-mono text-muted-foreground">{user.id}</span>
        </div>
      </div>
    </div>
    </div>
  )
}

