import { useState, useMemo } from "react"
import { ArrowDownLeft, ArrowUpRight, Plus, CreditCard, ChevronDown } from "lucide-react"
import { cn } from "@/lib/utils"
import { Skeleton } from "./ui/skeleton"
import { Button } from "./ui/button"
import { Badge } from "./ui/badge"
import { formatCurrency } from "@/lib/utils"
import type { IWalletTransaction, ITransaction, TBankAccountNumber } from "@/types"

const PAGE_SIZE = 25

type TimelineEventType = "deposit" | "transfer_incoming" | "transfer_outgoing" | "account_created"

interface TimelineEvent {
  id: string
  type: TimelineEventType
  description: string
  amount: string
  status?: string
  timestamp: string
  href: string
}

function eventIcon(type: TimelineEventType) {
  switch (type) {
    case "transfer_incoming":
      return <ArrowDownLeft className="size-4" />
    case "transfer_outgoing":
      return <ArrowUpRight className="size-4" />
    case "deposit":
      return <Plus className="size-4" />
    case "account_created":
      return <CreditCard className="size-4" />
  }
}

function eventColor(type: TimelineEventType): string {
  switch (type) {
    case "transfer_incoming":
      return "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400"
    case "transfer_outgoing":
      return "bg-muted text-muted-foreground"
    case "deposit":
      return "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400"
    case "account_created":
      return "bg-blue-500/10 text-blue-600 dark:text-blue-400"
  }
}

function dayLabel(dateStr: string): string {
  const date = new Date(dateStr + "T00:00:00")
  const today = new Date()
  const todayStr = today.toISOString().slice(0, 10)
  const yesterday = new Date(today)
  yesterday.setDate(yesterday.getDate() - 1)
  const yesterdayStr = yesterday.toISOString().slice(0, 10)

  if (dateStr === todayStr) return "Today"
  if (dateStr === yesterdayStr) return "Yesterday"
  return date.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })
}

function formatTime(iso: string): string {
  const date = new Date(iso)
  return date.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })
}

function statusBadgeVariant(status: string): "default" | "secondary" | "destructive" {
  if (status === "success") return "default"
  if (status === "failed") return "destructive"
  return "secondary"
}

function buildEvents(
  transactions: ITransaction[],
  accounts: IWalletTransaction[],
  userAccountNumbers: Set<string>
): TimelineEvent[] {
  const events: TimelineEvent[] = []

  for (const tx of transactions) {
    const senderStr = String(tx.senderAccountNumber)
    const receiverStr = String(tx.receiverAccountNumber)
    const isSender = userAccountNumbers.has(senderStr)
    const isReceiver = userAccountNumbers.has(receiverStr)

    let type: TimelineEventType
    let description: string

    if (senderStr === receiverStr) {
      type = "deposit"
      description = "Deposit"
    } else if (isSender) {
      type = "transfer_outgoing"
      description = `To ${tx.receiverName}`
    } else if (isReceiver) {
      type = "transfer_incoming"
      description = `From ${tx.senderName}`
    } else {
      type = "transfer_outgoing"
      description = `To ${tx.receiverName}`
    }

    events.push({
      id: `tx-${tx.id}`,
      type,
      description,
      amount: tx.amount,
      status: tx.status,
      timestamp: tx.createdAt,
      href: `/transactions/${tx.id}`,
    })
  }

  for (const acc of accounts) {
    events.push({
      id: `acct-${acc.id}`,
      type: "account_created",
      description: `${acc.name} created`,
      amount: "",
      timestamp: acc.createdAt instanceof Date ? acc.createdAt.toISOString() : String(acc.createdAt),
      href: `/account/${acc.accountNumber}`,
    })
  }

  events.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
  return events
}

function groupByDay(events: TimelineEvent[]): Map<string, TimelineEvent[]> {
  const groups = new Map<string, TimelineEvent[]>()
  for (const event of events) {
    const day = event.timestamp.slice(0, 10)
    const existing = groups.get(day)
    if (existing) {
      existing.push(event)
    } else {
      groups.set(day, [event])
    }
  }
  return groups
}

interface ActivityTimelineProps {
  transactions: ITransaction[]
  accounts: IWalletTransaction[]
  userAccountNumbers: Set<string>
  loading: boolean
  error: string | null
  onRetry: () => void
}

export default function ActivityTimeline({
  transactions,
  accounts,
  userAccountNumbers,
  loading,
  error,
  onRetry,
}: ActivityTimelineProps) {
  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE)

  const events = useMemo(
    () => buildEvents(transactions, accounts, userAccountNumbers),
    [transactions, accounts, userAccountNumbers]
  )

  const dayGroups = useMemo(() => groupByDay(events), [events])

  const flatEvents = useMemo(() => {
    const result: { day: string; event: TimelineEvent }[] = []
    for (const [day, dayEvents] of dayGroups) {
      for (const event of dayEvents) {
        result.push({ day, event })
      }
    }
    return result
  }, [dayGroups])

  const visibleEvents = flatEvents.slice(0, visibleCount)
  const hasMore = flatEvents.length > visibleCount

  if (loading) {
    return (
      <div className="space-y-1">
        <div className="sticky top-0 z-10 bg-background/80 backdrop-blur-sm py-3">
          <Skeleton className="h-5 w-24" />
        </div>
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="flex items-center gap-3 px-2 py-3">
            <Skeleton className="size-8 rounded-full shrink-0" />
            <div className="flex-1 space-y-1.5">
              <Skeleton className="h-4 w-48" />
              <Skeleton className="h-3 w-24" />
            </div>
            <Skeleton className="h-4 w-20" />
          </div>
        ))}
      </div>
    )
  }

  if (error) {
    return (
      <div className="flex flex-col items-center gap-3 py-16 text-center">
        <p className="text-sm text-muted-foreground">{error}</p>
        <Button variant="outline" size="sm" onClick={onRetry}>
          Retry
        </Button>
      </div>
    )
  }

  if (events.length === 0) {
    return (
      <div className="flex flex-col items-center gap-2 py-16 text-center">
        <p className="text-sm text-muted-foreground">No activity yet</p>
      </div>
    )
  }

  let lastDay = ""

  return (
    <div>
      {visibleEvents.map(({ day, event }) => {
        const showDayHeader = day !== lastDay
        lastDay = day

        return (
          <div key={event.id}>
            {showDayHeader && (
              <div className="sticky top-0 z-10 bg-background/80 backdrop-blur-sm py-3">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                  {dayLabel(day)}
                </p>
              </div>
            )}
            <a
              href={event.href}
              className={cn(
                "flex items-center gap-3 px-2 py-3 rounded-lg transition-colors",
                "hover:bg-surface-hover cursor-pointer -mx-2"
              )}
            >
              <div className={cn("size-8 rounded-full flex items-center justify-center shrink-0", eventColor(event.type))}>
                {eventIcon(event.type)}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-foreground truncate">{event.description}</p>
                <p className="text-xs text-muted-foreground">{formatTime(event.timestamp)}</p>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                {event.amount && (
                  <span className="font-mono text-sm font-semibold whitespace-nowrap tabular-nums">
                    {formatCurrency(event.amount)}
                  </span>
                )}
                {event.status && (
                  <Badge variant={statusBadgeVariant(event.status)} className="text-[10px] px-1.5 py-0">
                    {event.status}
                  </Badge>
                )}
              </div>
            </a>
          </div>
        )
      })}

      {hasMore && (
        <div className="flex justify-center pt-4 pb-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setVisibleCount((c) => c + PAGE_SIZE)}
          >
            <ChevronDown className="size-4 mr-1" />
            Show more
          </Button>
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from "react"
import { useParams, Link } from "@tanstack/react-router"
import { ArrowLeft } from "lucide-react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { fetchTransactionsAction } from "@/actions/transaction.actions"
import { getLedgerEntries } from "@/actions/account.actions"
import type { ITransaction, ILedgerEntry } from "@/types"
import { formatCurrency } from "@/lib/utils"

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso))

type Direction = "in" | "out" | "self"

export default function TransactionDetailPage() {
  const { data: session } = useSession()
  const user = session!.user
  const params = useParams({ from: "/transactions/$transactionId" })
  const transactionId = params.transactionId

  const [transaction, setTransaction] = useState<ITransaction | null>(null)
  const [accounts, setAccounts] = useState<Set<string>>(new Set())
  const [ledger, setLedger] = useState<ILedgerEntry[]>([])
  const [loading, setLoading] = useState(true)
  const [ledgerLoading, setLedgerLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const getDirection = (tx: ITransaction): Direction => {
    if (tx.senderName === tx.receiverName) return "self"
    const senderIn = accounts.has(tx.senderAccountNumber.toString())
    const receiverIn = accounts.has(tx.receiverAccountNumber.toString())
    if (receiverIn && !senderIn) return "in"
    return "out"
  }

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      setError(null)
      try {
        const [txRes, accRes] = await Promise.all([
          fetchTransactionsAction(user.id),
          fetch("/api/wallet/users/" + user.id + "/accounts"),
        ])

        const accJson = await accRes.json()
        const accountIds = new Set<string>()
        if (accJson.ok && Array.isArray(accJson.data)) {
          accJson.data.forEach((a: { id: string }) => accountIds.add(a.id))
        }
        setAccounts(accountIds)

        if (!txRes.ok) throw new Error(txRes.error ?? "Failed to load transaction")
        const found = (txRes.data ?? []).find((tx) => tx.id === transactionId)
        if (!found) throw new Error("Transaction not found")
        setTransaction(found)
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load transaction")
      } finally {
        setLoading(false)
      }
    }
    load()
  }, [user.id, transactionId])

  useEffect(() => {
    if (!transaction) return
    setLedgerLoading(true)
    getLedgerEntries(transactionId)
      .then((res) => {
        if (res.ok) setLedger(res.data ?? [])
      })
      .catch(() => {})
      .finally(() => setLedgerLoading(false))
  }, [transaction, transactionId])

  const dir = transaction ? getDirection(transaction) : null

  const detailRow = (label: string, value: string) => (
    <div className="flex items-baseline justify-between gap-4 py-2 border-b border-border/30 last:border-0">
      <span className="text-sm text-muted-foreground shrink-0">{label}</span>
      <span className="text-sm font-medium text-foreground text-right font-mono break-all">{value}</span>
    </div>
  )

  return (
    <>
      <PageHeader
        title={loading ? <Skeleton className="h-6 w-40" /> : "Transaction Details"}
        email={user.email}
        beforeTitle={
          <Link
            to="/transactions"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Transactions"
          >
            <ArrowLeft className="size-4" />
          </Link>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-8 space-y-6">
        {loading && (
          <Card>
            <CardContent className="p-6 space-y-4">
              <Skeleton className="h-4 w-24" />
              <Skeleton className="h-10 w-48" />
              <Skeleton className="h-4 w-36" />
              <Skeleton className="h-4 w-56" />
              <Skeleton className="h-4 w-40" />
            </CardContent>
          </Card>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center gap-3 py-10 text-center">
            <p className="text-sm text-muted-foreground">{error}</p>
            <Link to="/transactions">
              <span className="inline-flex items-center justify-center rounded-md bg-primary text-primary-foreground h-9 px-4 text-sm font-medium">Back to Transactions</span>
            </Link>
          </div>
        )}

        {!loading && !error && transaction && (
          <>
            <Card>
              <CardContent className="p-6 space-y-5">
                <div className="flex items-start justify-between">
                  <div className="space-y-1">
                    <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Amount</p>
                    <p className={`text-3xl font-semibold font-mono tracking-tight ${
                      dir === "in" ? "text-success" : "text-foreground"
                    }`}>
                      {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}
                      {formatCurrency(transaction.amount)}
                    </p>
                  </div>
                  <Badge
                    variant={transaction.status === "success" ? "default" : transaction.status === "failed" ? "destructive" : "secondary"}
                    className="text-xs"
                  >
                    {transaction.status}
                  </Badge>
                </div>

                <div className="pt-2 border-t border-border/50 space-y-0">
                  <div className="grid grid-cols-2 gap-4 pb-4 border-b border-border/30">
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">From</p>
                      <p className="text-sm font-medium text-foreground">{transaction.senderName}</p>
                      <p className="text-xs font-mono text-muted-foreground">{String(transaction.senderAccountNumber)}</p>
                    </div>
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">To</p>
                      <p className="text-sm font-medium text-foreground">{transaction.receiverName}</p>
                      <p className="text-xs font-mono text-muted-foreground">{String(transaction.receiverAccountNumber)}</p>
                    </div>
                  </div>

                  {detailRow("Transaction ID", transaction.id)}
                  {detailRow("Created", formatDate(transaction.createdAt))}
                  {transaction.updatedAt && detailRow("Updated", formatDate(transaction.updatedAt))}
                  {detailRow("Type", dir === "self" ? "Deposit" : dir === "in" ? "Incoming Transfer" : "Outgoing Transfer")}
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium">Ledger Entries</CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                {ledgerLoading && (
                  <div className="space-y-3 p-6">
                    {Array.from({ length: 2 }).map((_, i) => (
                      <Skeleton key={i} className="h-10 w-full rounded-md" />
                    ))}
                  </div>
                )}
                {!ledgerLoading && ledger.length === 0 && (
                  <div className="py-8 text-center px-6">
                    <p className="text-sm text-muted-foreground">No ledger entries available.</p>
                  </div>
                )}
                {!ledgerLoading && ledger.length > 0 && (
                  <div className="divide-y divide-border/30">
                    {ledger.map((entry) => (
                      <div key={entry.id} className="flex items-center justify-between px-6 py-3.5">
                        <div className="flex items-center gap-3">
                          <div className={`w-2 h-2 rounded-full ${
                            entry.entryType === "debit" ? "bg-destructive" : "bg-success"
                          }`} />
                          <span className="text-sm font-medium text-foreground capitalize">{entry.entryType}</span>
                        </div>
                        <span className="text-sm font-mono text-foreground">{formatCurrency(entry.amount)}</span>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </>
        )}
      </main>

      <PageFooter
        right={transaction && <span>ID: {transaction.id.slice(0, 8)}&hellip;</span>}
      />
    </>
  )
}

import { useEffect, useState, useCallback, useMemo } from "react"
import { useParams, Link } from "@tanstack/react-router"
import { ArrowLeft, Eye, EyeOff, MoreVertical } from "lucide-react"
import { useSession } from "../lib/auth-client"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "../components/ui/dropdown-menu"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { fetchAccountData } from "@/actions/account.actions"
import { fetchTransactionsAction } from "@/actions/transaction.actions"
import type { IWalletTransaction, ITransaction, WaveResponse } from "@/types"
import { formatCurrency } from "@/lib/utils"

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso))

type Direction = "in" | "out" | "self"

export default function AccountDetailPage() {
  const { data: session } = useSession()
  const user = session!.user
  const params = useParams({ from: "/account/$accountNumber" })
  const accountNumberParam = params.accountNumber

  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [loading, setLoading] = useState(true)
  const [transactionsLoading, setTransactionsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showBalance, setShowBalance] = useState(true)

  const account = useMemo(
    () => accounts.find((a) => String(a.accountNumber) === accountNumberParam) ?? null,
    [accounts, accountNumberParam],
  )

  const getDirection = useCallback(
    (tx: ITransaction): Direction => {
      const txSender = String(tx.senderAccountNumber)
      const txReceiver = String(tx.receiverAccountNumber)
      if (txSender === txReceiver) return "self"
      if (txReceiver === accountNumberParam) return "in"
      if (txSender === accountNumberParam) return "out"
      return "out"
    },
    [accountNumberParam],
  )

  const accountTransactions = useMemo(
    () =>
      transactions.filter((tx) => {
        const sender = String(tx.senderAccountNumber)
        const receiver = String(tx.receiverAccountNumber)
        return sender === accountNumberParam || receiver === accountNumberParam
      }),
    [transactions, accountNumberParam],
  )

  const recentTransactions = useMemo(() => accountTransactions.slice(0, 10), [accountTransactions])

  const fetchAccounts = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const res = await fetchAccountData(user.id)
      if (!res.ok) {
        setError(res.error ?? "Failed to load account")
        return
      }
      setAccounts(res.data)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load account")
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const fetchTransactions = useCallback(async () => {
    setTransactionsLoading(true)
    try {
      const res = await fetchTransactionsAction(user.id)
      if (res.ok) {
        const sorted = (res.data ?? []).sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
        )
        setTransactions(sorted)
      }
    } catch {
      // silently fail for transactions
    } finally {
      setTransactionsLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
    fetchTransactions()
  }, [fetchAccounts, fetchTransactions])

  const pageTitle = account?.name ?? "Account Details"

  return (
    <>
      <PageHeader
        title={loading ? <Skeleton className="h-6 w-40" /> : pageTitle}
        email={user.email}
        beforeTitle={
          <Link
            to="/account"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Account"
          >
            <ArrowLeft className="size-4" />
          </Link>
        }
        actions={
          account && (
            <DropdownMenu>
              <DropdownMenuTrigger className="w-8 h-8 border border-input bg-background">
                <MoreVertical className="size-4" />
              </DropdownMenuTrigger>
              <DropdownMenuContent>
                <DropdownMenuItem onClick={() => window.location.href = "/account/settings"}>
                  Edit
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => window.location.href = "/account/transactions"}>
                  All Transactions
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          )
        }
      />

          <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-8 space-y-6">
            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-10 text-center">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchAccounts}>
                  Retry
                </Button>
              </div>
            )}

            {loading && (
              <Card>
                <CardContent className="p-6 space-y-4">
                  <Skeleton className="h-4 w-24" />
                  <Skeleton className="h-10 w-48" />
                  <Skeleton className="h-4 w-36" />
                  <Skeleton className="h-4 w-56" />
                </CardContent>
              </Card>
            )}

            {!loading && !error && account && (
              <>
                <Card>
                  <CardContent className="p-6 space-y-5">
                    <div className="flex items-start justify-between">
                      <div className="space-y-1">
                        <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                          Current Balance
                        </p>
                        <div className="flex items-center gap-2">
                          <p
                            className={`text-3xl font-semibold font-mono tracking-tight transition-all duration-300 ${
                              !showBalance ? "blur-lg select-none" : ""
                            }`}
                            aria-hidden={!showBalance}
                          >
                            {formatCurrency(account.balance)}
                          </p>
                          <button
                            type="button"
                            onClick={() => setShowBalance((v) => !v)}
                            className="flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
                            aria-label={showBalance ? "Hide balance" : "Show balance"}
                          >
                            {showBalance ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                          </button>
                        </div>
                      </div>
                      <Badge variant="secondary" className="text-xs">
                        Active
                      </Badge>
                    </div>

                    <div className="grid grid-cols-2 gap-4 pt-2 border-t border-border/50">
                      <div className="space-y-1">
                        <p className="text-xs text-muted-foreground">Account Number</p>
                        <p className="text-sm font-mono text-foreground">
                          {String(account.accountNumber)}
                        </p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-xs text-muted-foreground">Created</p>
                        <p className="text-sm text-foreground">
                          {formatDate(String(account.createdAt))}
                        </p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-xs text-muted-foreground">Account Name</p>
                        <p className="text-sm text-foreground">{account.name}</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-xs text-muted-foreground">Monthly Volume</p>
                        <p className="text-sm text-foreground">
                          {formatCurrency(accountTransactions.reduce((sum, tx) => sum + Number(tx.amount), 0))}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                <div className="grid grid-cols-2 gap-4">
                  <Link
                    to="/account"
                    search={{ section: "deposit" }}
                    className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary text-primary-foreground h-12 text-sm font-semibold transition-colors hover:opacity-90"
                  >
                    Add Money
                  </Link>
                  <Link
                    to="/account"
                    className="inline-flex items-center justify-center gap-2 rounded-xl bg-surface text-foreground h-12 text-sm font-semibold transition-colors hover:bg-surface-hover border border-border"
                  >
                    Send Money
                  </Link>
                </div>

                <Card>
                  <CardHeader className="flex flex-row items-center justify-between pb-4">
                    <CardTitle className="text-sm font-medium">
                      Recent Transactions
                    </CardTitle>
                    <Link
                      to="/account/transactions"
                      className="text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
                    >
                      View all
                    </Link>
                  </CardHeader>
                  <CardContent className="p-0">
                    {transactionsLoading && (
                      <div className="space-y-3 p-6">
                        {Array.from({ length: 4 }).map((_, i) => (
                          <Skeleton key={i} className="h-12 w-full rounded-md" />
                        ))}
                      </div>
                    )}

                    {!transactionsLoading && recentTransactions.length === 0 && (
                      <div className="py-10 text-center px-6">
                        <p className="text-sm text-muted-foreground">
                          No transactions yet for this account.
                        </p>
                      </div>
                    )}

                    {!transactionsLoading && recentTransactions.length > 0 && (
                      <div className="divide-y divide-border/30">
                        {recentTransactions.map((tx) => {
                          const dir = getDirection(tx)
                          const amount = Number(tx.amount)
                          return (
                            <div
                              key={tx.id}
                              className="flex items-center gap-4 px-6 py-4 transition-colors hover:bg-surface-hover cursor-pointer"
                              onClick={() => window.location.href = `/transactions/${tx.id}`}
                            >
                              <div className="shrink-0 w-9 h-9 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
                                {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
                              </div>
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-foreground truncate">
                                  {dir === "self"
                                    ? "Deposit"
                                    : dir === "in"
                                      ? `From ${tx.senderName}`
                                      : `To ${tx.receiverName}`}
                                </p>
                                <p className="text-xs text-muted-foreground">
                                  {formatDate(tx.createdAt)}
                                </p>
                              </div>
                              <div className="text-right">
                                <p
                                  className={`text-sm font-mono font-semibold whitespace-nowrap ${
                                    dir === "in" ? "text-success" : "text-foreground"
                                  }`}
                                >
                                  {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}
                                  {formatCurrency(amount)}
                                </p>
                                <Badge
                                  variant={
                                    tx.status === "success"
                                      ? "default"
                                      : tx.status === "failed"
                                        ? "destructive"
                                        : "secondary"
                                  }
                                  className="text-[10px] px-1.5 py-0 mt-0.5"
                                >
                                  {tx.status}
                                </Badge>
                              </div>
                            </div>
                          )
                        })}
                      </div>
                    )}
                  </CardContent>
                </Card>
              </>
            )}

            {!loading && !error && !account && (
              <div className="flex flex-col items-center gap-3 py-10 text-center">
                <p className="text-sm text-muted-foreground">Account not found.</p>
                <Link to="/account">
                  <Button variant="outline" size="sm">
                    Back to Accounts
                  </Button>
                </Link>
              </div>
            )}
          </main>

      <PageFooter
        right={
          <span>
            {accountTransactions.length} transaction{accountTransactions.length !== 1 ? "s" : ""}
          </span>
        }
      />
    </>
  )
}

import { useEffect, useState, useCallback, useMemo, useRef } from "react"
import { Search, X } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { formatCurrency } from "@/lib/utils"
import type { IWalletTransaction, WaveResponse, ITransaction, TBankAccountNumber } from "@/types"

type ResourceType = "transaction" | "account" | "notification"

interface SearchResult {
  id: string
  type: ResourceType
  title: string
  subtitle: string
  href: string
  amount?: string
  timestamp: string
  status?: string
}

interface RawNotification {
  id: string
  title: string
  message: string
  type: "info" | "warning" | "error"
  timestamp: string
  read: boolean
}

const TABS: { key: ResourceType | "all"; label: string }[] = [
  { key: "all", label: "All" },
  { key: "transaction", label: "Transactions" },
  { key: "account", label: "Accounts" },
  { key: "notification", label: "Notifications" },
]

function formatDate(iso: string): string {
  const d = new Date(iso)
  const now = new Date()
  const diffMs = now.getTime() - d.getTime()
  const diffMins = Math.floor(diffMs / 60000)
  if (diffMins < 1) return "Just now"
  if (diffMins < 60) return `${diffMins}m ago`
  const diffHours = Math.floor(diffMins / 60)
  if (diffHours < 24) return `${diffHours}h ago`
  const diffDays = Math.floor(diffHours / 24)
  if (diffDays < 7) return `${diffDays}d ago`
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" })
}

function typeBadgeVariant(type: ResourceType): "default" | "secondary" | "outline" {
  switch (type) {
    case "transaction": return "default"
    case "account": return "secondary"
    case "notification": return "outline"
  }
}

function typeLabel(type: ResourceType): string {
  switch (type) {
    case "transaction": return "Transaction"
    case "account": return "Account"
    case "notification": return "Notification"
  }
}

export default function SearchPage() {
  const { data: session } = useSession()
  const user = session!.user

  const [query, setQuery] = useState("")
  const [activeTab, setActiveTab] = useState<ResourceType | "all">("all")
  const inputRef = useRef<HTMLInputElement>(null)

  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [notifications, setNotifications] = useState<RawNotification[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchAll = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const [txRes, acctRes, notifRes] = await Promise.all([
        fetch(`/api/wallet/users/${user.id}/transactions`),
        fetch(`/api/wallet/users/${user.id}/accounts`),
        fetch(`/api/notification/users/${user.id}/notifications?limit=100`),
      ])

      const [txJson, acctJson, notifJson]: [
        WaveResponse<ITransaction[]>,
        WaveResponse<IWalletTransaction[]>,
        { ok: boolean; data?: RawNotification[] }
      ] = await Promise.all([
        txRes.json(),
        acctRes.json(),
        notifRes.json(),
      ])

      if (txJson.ok) setTransactions(txJson.data)
      if (acctJson.ok) setAccounts(acctJson.data)
      if (notifJson.ok) setNotifications(notifJson.data ?? [])
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load data")
    } finally {
      setLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAll()
  }, [fetchAll])

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const results = useMemo(() => {
    const q = query.trim().toLowerCase()
    const items: SearchResult[] = []

    if (!q) return items

    for (const tx of transactions) {
      const senderStr = String(tx.senderAccountNumber)
      const receiverStr = String(tx.receiverAccountNumber)
      const searchable = [
        tx.senderName.toLowerCase(),
        tx.receiverName.toLowerCase(),
        senderStr,
        receiverStr,
        tx.amount,
        tx.status,
      ]
      if (!searchable.some((s) => s.includes(q))) continue

      items.push({
        id: `tx-${tx.id}`,
        type: "transaction",
        title: tx.senderName === tx.receiverName
          ? "Deposit"
          : `To ${tx.receiverName}`,
        subtitle: tx.senderName === tx.receiverName
          ? `From ${tx.senderName}`
          : `From ${tx.senderName}`,
        amount: tx.amount,
        status: tx.status,
        timestamp: tx.createdAt,
        href: `/transactions/${tx.id}`,
      })
    }

    for (const acct of accounts) {
      const searchable = [
        acct.name.toLowerCase(),
        String(acct.accountNumber),
        String(acct.balance),
      ]
      if (!searchable.some((s) => s.includes(q))) continue

      items.push({
        id: `acct-${acct.id}`,
        type: "account",
        title: acct.name,
        subtitle: `Account ${acct.accountNumber}`,
        amount: String(acct.balance),
        timestamp: acct.createdAt instanceof Date
          ? acct.createdAt.toISOString()
          : String(acct.createdAt),
        href: `/account/${acct.accountNumber}`,
      })
    }

    for (const notif of notifications) {
      const searchable = [
        notif.title.toLowerCase(),
        notif.message.toLowerCase(),
      ]
      if (!searchable.some((s) => s.includes(q))) continue

      items.push({
        id: `notif-${notif.id}`,
        type: "notification",
        title: notif.title,
        subtitle: notif.message,
        timestamp: notif.timestamp,
        href: "/notifications",
      })
    }

    items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
    return items
  }, [query, transactions, accounts, notifications])

  const filteredResults = useMemo(() => {
    if (activeTab === "all") return results
    return results.filter((r) => r.type === activeTab)
  }, [results, activeTab])

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <PageHeader
        title="Search"
        email={user.email}
        actions={
          <Button variant="ghost" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-3xl px-8 py-8 space-y-6">
        <div className="relative">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 size-5 text-muted-foreground pointer-events-none" />
          <Input
            ref={inputRef}
            placeholder="Search transactions, accounts, notifications..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 pr-10 h-12 text-base rounded-xl"
          />
          {query && (
            <button
              onClick={() => setQuery("")}
              className="absolute right-3.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
              aria-label="Clear search"
            >
              <X className="size-5" />
            </button>
          )}
        </div>

        {loading && (
          <div className="space-y-3">
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="flex items-center gap-3 px-3 py-3">
                <Skeleton className="size-8 rounded-full shrink-0" />
                <div className="flex-1 space-y-1.5">
                  <Skeleton className="h-4 w-48" />
                  <Skeleton className="h-3 w-32" />
                </div>
                <Skeleton className="h-4 w-16" />
              </div>
            ))}
          </div>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center gap-3 py-16 text-center">
            <p className="text-sm text-muted-foreground">{error}</p>
            <Button variant="outline" size="sm" onClick={fetchAll}>
              Retry
            </Button>
          </div>
        )}

        {!loading && !error && query && (
          <>
            <div className="flex flex-wrap items-center gap-2">
              {TABS.map((tab) => {
                const count = tab.key === "all"
                  ? results.length
                  : results.filter((r) => r.type === tab.key).length
                return (
                  <button
                    key={tab.key}
                    onClick={() => setActiveTab(tab.key)}
                    className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                      activeTab === tab.key
                        ? "bg-primary text-primary-foreground"
                        : "bg-surface text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {tab.label}
                    <span className="text-[10px] opacity-70">({count})</span>
                  </button>
                )
              })}
            </div>

            {filteredResults.length === 0 ? (
              <div className="flex flex-col items-center gap-2 py-16 text-center">
                <p className="text-sm text-muted-foreground">No results found for &ldquo;{query}&rdquo;</p>
              </div>
            ) : (
              <div>
                <p className="text-xs text-muted-foreground mb-3">
                  {filteredResults.length} result{filteredResults.length !== 1 ? "s" : ""}
                </p>
                <div className="divide-y divide-border/30">
                  {filteredResults.map((result) => (
                    <a
                      key={result.id}
                      href={result.href}
                      className="flex items-center gap-3 px-3 py-3 rounded-lg transition-colors hover:bg-surface-hover -mx-3"
                    >
                      <Badge variant={typeBadgeVariant(result.type)} className="shrink-0 text-[10px] px-1.5 py-0">
                        {typeLabel(result.type)}
                      </Badge>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-foreground truncate">{result.title}</p>
                        <p className="text-xs text-muted-foreground truncate">{result.subtitle}</p>
                      </div>
                      <div className="text-right shrink-0">
                        {result.amount && (
                          <p className="font-mono text-sm font-semibold whitespace-nowrap tabular-nums">
                            {formatCurrency(result.amount)}
                          </p>
                        )}
                        <p className="text-[10px] text-muted-foreground">{formatDate(result.timestamp)}</p>
                      </div>
                    </a>
                  ))}
                </div>
              </div>
            )}
          </>
        )}

        {!loading && !error && !query && (
          <div className="flex flex-col items-center gap-2 py-16 text-center">
            <Search className="size-10 text-muted-foreground/40 mb-2" />
            <p className="text-sm text-muted-foreground">
              Search across your transactions, accounts, and notifications
            </p>
          </div>
        )}
      </main>

      <PageFooter />
    </>
  )
}

